def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.2))

    prev_bids = []
    urgent_prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_highest_prev = max(urgent_prev_bids) if urgent_prev_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.7
    elif hp <= 4:
        danger += 0.35
    if no_water_days >= 2:
        danger += 0.8
    elif no_water_days >= 1:
        danger += 0.35
    if danger > 1.0:
        danger = 1.0

    affordable_soft = min(budget, DAILY_SALARY * (0.45 + 0.35 * scarcity))
    affordable_hard = min(budget, DAILY_SALARY * (0.9 + 0.5 * scarcity))

    if supply >= 22 and danger < 0.35:
        bid = DAILY_SALARY * 0.18
    elif danger >= 0.85:
        target = max(DAILY_SALARY * 1.05, urgent_highest_prev + 2.0)
        bid = min(budget, target)
    elif danger >= 0.45:
        target = max(DAILY_SALARY * (0.72 + 0.18 * scarcity), urgent_highest_prev + 1.5)
        bid = min(budget, target)
    elif supply <= 17:
        if highest_prev >= DAILY_SALARY * 1.8:
            bid = min(budget, DAILY_SALARY * 0.28)
        else:
            target = max(DAILY_SALARY * (0.52 + 0.18 * scarcity), highest_prev + 1.0)
            bid = min(affordable_soft, target)
    else:
        anchor = DAILY_SALARY * (0.3 + 0.22 * scarcity)
        if highest_prev > 0:
            anchor = max(anchor, highest_prev * 0.82)
        bid = min(budget, anchor)

    reserve_floor = 0.0
    if hp >= 6 and no_water_days == 0:
        reserve_floor = DAILY_SALARY * 0.15
        if bid > budget - reserve_floor:
            bid = max(0.0, budget - reserve_floor)

    if danger >= 0.45:
        bid = min(budget, max(bid, DAILY_SALARY * 0.55))

    if supply >= 24 and danger < 0.45:
        bid = min(bid, DAILY_SALARY * 0.22)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQUIREMENT = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # If no opponents, bid minimum to conserve budget
    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Survival mode: If HP is very low or I missed water yesterday
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # End game strategy: Bid more aggressively in the last few days
    if day_context['day'] >= EPISODE_DAYS - 2: 
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive'] and opp_data.get('previous_trace') and opp_data['previous_trace'].get('bid') is not None:
            yesterday_bids.append(opp_data['previous_trace']['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0

    # Dynamic Bidding based on supply and competition
    actual_water_units_available = day_context['supply']
    num_possible_winners = int(actual_water_units_available / WATER_REQUIREMENT)

    bid = DAILY_SALARY * 0.5 # Default bid

    if num_possible_winners >= num_alive_opponents + 1:
        # Abundant supply: Enough for everyone. Bid moderately.
        if highest_prev_bid > 0:
            bid = max(DAILY_SALARY * 0.4, highest_prev_bid * 0.9)
        else: # First day or no previous bids
            bid = DAILY_SALARY * 0.45
    else:
        # Scarce supply or moderate supply: Competition is higher. Bid more aggressively.
        if highest_prev_bid > 0:
            bid = max(DAILY_SALARY * 0.7, highest_prev_bid + 5)
        else: # First day or no previous bids
            bid = DAILY_SALARY * 0.6

    # Ensure bid does not exceed budget
    final_bid = min(my_status['budget'], bid)

    # Ensure a minimum bid if budget allows
    if final_bid < DAILY_SALARY * 0.1 and my_status['budget'] >= DAILY_SALARY * 0.1:
        final_bid = DAILY_SALARY * 0.1
    elif final_bid <= 0 and my_status['budget'] > 0:
        final_bid = 1.0 

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday = max(yesterday_bids) if yesterday_bids else 0
    hp = my_status['hp']
    budget = my_status['budget']

    if hp <= 2:
        # desperate: try to outbid yesterday's max by small margin, cap at budget
        target = max(DAILY_SALARY * 1.2, max_yesterday + 2)
    elif hp <= 5:
        # moderate risk: bid slightly above average, but not overbudget
        avg_yesterday = sum(yesterday_bids)/len(yesterday_bids) if yesterday_bids else DAILY_SALARY * 0.5
        target = min(max_yesterday * 0.9, avg_yesterday + 5)
    else:
        # comfortable: low bid to save budget
        target = DAILY_SALARY * 0.3

    return min(budget, max(0, target))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_agents = len(alive_opponents) + 1

    # Calculate estimated fair bid based on remaining supply
    fair_bid = (DAILY_SALARY * 0.6) if supply / num_agents >= WATER_REQ else (DAILY_SALARY * 0.85)

    # Adjust for health
    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Observe yesterday's max bid to avoid overpaying
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace')]
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > DAILY_SALARY * 0.9:
            return min(my_status['budget'], DAILY_SALARY * 0.4)
        return min(my_status['budget'], max(fair_bid, max_prev + 2.0))

    return min(my_status['budget'], fair_bid)
